examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space3) {
    MonarchAiThread(
        [
            MonarchAiConversationMessage(
                id: {{messages.0.id}},
                role: {{messages.0.role|case}},
                parts: [.text(MonarchAiTextPart(text: {{messages.0.text}}))],
                createdAt: {{messages.0.createdAt}}
            ),
            MonarchAiConversationMessage(
                id: {{messages.1.id}},
                role: {{messages.1.role|case}},
                parts: [.text(MonarchAiTextPart(text: {{messages.1.text}}))],
                agent: MonarchAiAgentRef(name: {{messages.1.agent.name}}, role: {{messages.1.agent.role}}),
                createdAt: {{messages.1.createdAt}}
            ),
        ],
        now: {{now|date}}
    )
    .frame(height: 560)
    .overlay(RoundedRectangle(cornerRadius: 4).strokeBorder(theme.colors.borderSubtle))
    HStack(spacing: theme.spacing.space2) {
        MonarchButton("Send a message", variant: .primary) {}
        MonarchButton("Stop", variant: .secondary) {}
            .disabled(true)
    }
}
.environment(\.locale, Locale(identifier: {{locale}}))
.environment(\.timeZone, TimeZone(identifier: {{timeZone}}) ?? .gmt)

examples.code:
VStack(alignment: .leading, spacing: theme.spacing.space3) {
    MonarchAiThread(
        [
            MonarchAiConversationMessage(
                id: "turn-1",
                role: .user,
                parts: [.text(MonarchAiTextPart(text: "Summarise the meeting notes"))],
                createdAt: "2026-11-04T09:30:00Z"
            ),
            MonarchAiConversationMessage(
                id: "turn-2",
                role: .assistant,
                parts: [.text(MonarchAiTextPart(text: "The team agreed to move the launch to Thursday 12 November. Priya will update the release notes, and Sam will check the migration on staging before Wednesday. Two questions stay open: the pricing page copy and who signs off the support rota."))],
                agent: MonarchAiAgentRef(name: "Assistant", role: "Writing assistant"),
                createdAt: "2026-11-04T09:30:06Z"
            ),
        ],
        now: Date(timeIntervalSince1970: 1_793_784_660)
    )
    .frame(height: 560)
    .overlay(RoundedRectangle(cornerRadius: 4).strokeBorder(theme.colors.borderSubtle))
    HStack(spacing: theme.spacing.space2) {
        MonarchButton("Send a message", variant: .primary) {}
        MonarchButton("Stop", variant: .secondary) {}
            .disabled(true)
    }
}
.environment(\.locale, Locale(identifier: "en-GB"))
.environment(\.timeZone, TimeZone(identifier: "Europe/London") ?? .gmt)

examples.setup:
private let messages: [MonarchAiConversationMessage] = (0..<6).map { (index: Int) -> MonarchAiConversationMessage in
    MonarchAiConversationMessage(
        id: "m\(index)",
        role: index % 2 == 0 ? .user : .assistant,
        parts: [.text(MonarchAiTextPart(text: "Message \(index + 1)"))],
        createdAt: "2026-11-05T09:0\(index):00.000Z"
    )
}
@State private var isLoading = false

examples.code:
MonarchAiThread([], empty: {
    MonarchEmptyState("Ask anything", message: "Start a conversation with the assistant.")
})
.frame(height: 240)
